class Solution {
public:
    vector<int> mostSimilar(int n, vector<vector<int>>& roads,
                            vector<string>& names,
                            vector<string>& targetPath) {
        vector<vector<int>> graph(n);
        for (const auto& edge : roads) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }
        int length = targetPath.size();
        const int INF = 1000000000;
        vector<vector<int>> dp(length, vector<int>(n, INF));
        vector<vector<int>> previous(length, vector<int>(n, -1));
        for (int city = 0; city < n; ++city) {
            dp[0][city] = names[city] != targetPath[0];
        }
        for (int step = 1; step < length; ++step) {
            for (int city = 0; city < n; ++city) {
                for (int neighbor : graph[city]) {
                    int cost = dp[step - 1][neighbor]
                             + (names[city] != targetPath[step]);
                    if (cost < dp[step][city]) {
                        dp[step][city] = cost;
                        previous[step][city] = neighbor;
                    }
                }
            }
        }
        int city = min_element(dp.back().begin(), dp.back().end())
                 - dp.back().begin();
        vector<int> path(length);
        for (int step = length - 1; step >= 0; --step) {
            path[step] = city;
            city = previous[step][city];
        }
        return path;
    }
};
